import React, { Component } from 'react';

import { callPlayer, getSDK } from '../utils.js';

const SDK_URL = 'https://fast.wistia.com/assets/external/E-v1.js';
const SDK_GLOBAL = 'Wistia';
const MATCH_URL = /(?:wistia\.com|wi\.st)\/(?:medias|embed)\/(.*)$/;

export class Wistia extends Component<$TSFixMe> {
  static displayName = 'Wistia';

  static canPlay = (url: string) => MATCH_URL.test(url);

  static loopOnEnded = true;

  callPlayer = callPlayer;

  player: $TSFixMe;

  getID(url: $TSFixMe) {
    return url && url.match(MATCH_URL)[1];
  }

  load(url: $TSFixMe) {
    const { playing, muted, controls, onReady, config, onError } = this.props;
    getSDK(SDK_URL, SDK_GLOBAL).then(() => {
      // @ts-expect-error
      window._wq = window._wq || [];
      // @ts-expect-error
      window._wq.push({
        id: this.getID(url),
        options: {
          autoPlay: playing,
          silentAutoPlay: 'allow',
          muted,
          controlsVisibleOnLoad: controls,
          ...config.wistia.options,
        },
        onReady: (player: $TSFixMe) => {
          this.player = player;
          this.unbind();
          this.player.bind('play', this.onPlay);
          this.player.bind('pause', this.onPause);
          this.player.bind('seek', this.onSeek);
          this.player.bind('end', this.onEnded);
          onReady();
        },
      });
    }, onError);
  }

  unbind() {
    this.player.unbind('play', this.onPlay);
    this.player.unbind('pause', this.onPause);
    this.player.unbind('seek', this.onSeek);
    this.player.unbind('end', this.onEnded);
  }

  // Proxy methods to prevent listener leaks
  onPlay = (...args: $TSFixMe) => this.props.onPlay(...args);

  onPause = (...args: $TSFixMe) => this.props.onPause(...args);

  onSeek = (...args: $TSFixMe) => this.props.onSeek(...args);

  onEnded = (...args: $TSFixMe) => this.props.onEnded(...args);

  play() {
    this.callPlayer('play');
  }

  pause() {
    this.callPlayer('pause');
  }

  stop() {
    this.unbind();
    this.callPlayer('remove');
  }

  seekTo(seconds: $TSFixMe) {
    this.callPlayer('time', seconds);
  }

  setVolume(fraction: $TSFixMe) {
    this.callPlayer('volume', fraction);
  }

  mute = () => {
    this.callPlayer('mute');
  };

  unmute = () => {
    this.callPlayer('unmute');
  };

  setPlaybackRate(rate: $TSFixMe) {
    this.callPlayer('playbackRate', rate);
  }

  getDuration() {
    return this.callPlayer('duration');
  }

  getCurrentTime() {
    return this.callPlayer('time');
  }

  getSecondsLoaded() {
    return null;
  }

  render() {
    const id = this.getID(this.props.url);
    const className = `wistia_embed wistia_async_${id}`;
    const style = {
      width: '100%',
      height: '100%',
    };
    return <div key={id} className={className} style={style} />;
  }
}
